const instant = Date.parse('2031-03-04T05:06:07.000Z');
const digest = value => 'sha256:' + createHash('sha256').update(value).digest('hex');
const syntheticToken = 'synthetic-pr62-review-token-not-a-credential';
const pinned = { ref: 'test:evidence:review', sha256: digest('review'), pinned_revision: 'test:revision:review',
  independent_review: { ref: 'test:review:independent', sha256: digest('independent') } };

async function exercise(replaceTypeGuard) {
  const target = structuredClone(accessPlan({ cellId: 'image_generation', provider: 'openrouter' }).cells.find(c => c.cell_id === 'image_generation').target);
  const input = { run_id: 'test:review', cell_id: 'image_generation', target,
    configuration: target.configuration, scope: fixtureScope, grant_ref: 'grant:test:review',
    deadline_at: new Date(instant + 120000).toISOString() };
  const originalIsArray = Array.isArray;
  let hostCalls = 0, fetchCalls = 0, credentialCalls = 0, exposures = 0;
  let rawResponseExposures = 0, copiedResponseExposures = 0, replacementInstalled = false;
  let resolvedResponse;
  let observation;
  const host = { async prepare(value) {
    hostCalls += 1;
    assert.equal(value.credential.token, syntheticToken);
    assert.equal(this, host);
  }, async dispatch() { throw new Error('Dispatch is outside this probe'); } };
  try {
    const adapter = createOpenRouterImagesAdapter({ now: () => instant,
      fetchImpl: async () => { fetchCalls += 1; throw new Error('No transport is permitted'); },
      credentialPort: { evidence_mode: 'live', async resolveCredential(request) {
        credentialCalls += 1;
        resolvedResponse = { decision: 'resolved', evidence_mode: 'live', binding: {
          service: 'openrouter', account_ref: request.account_ref, project_ref: request.project_ref,
          target_binding_sha256: digest(JSON.stringify(request.target_binding)), grant_ref: request.grant_ref },
          token: syntheticToken, expires_at: new Date(instant + 600000).toISOString(), evidence: pinned };
        return resolvedResponse;
      } },
      get dispatchPort() {
        if (replaceTypeGuard) {
          replacementInstalled = true;
          Array.isArray = function(value) {
            if (value !== null && typeof value === 'object' && value.token === syntheticToken) {
              exposures += 1;
              if (value === resolvedResponse) rawResponseExposures += 1;
              else copiedResponseExposures += 1;
            }
            return originalIsArray(value);
          };
        }
        return host;
      }
    });
    const result = await adapter.prepare(input);
    observation = { result, replacementInstalled, hostCalls, fetchCalls, credentialCalls,
      exposures, rawResponseExposures, copiedResponseExposures, globalRestored: false };
    return observation;
  } finally {
    Array.isArray = originalIsArray;
    if (observation) observation.globalRestored = Array.isArray === originalIsArray;
  }
}

test('ordinary array guard keeps credential preparation private without transport', async () => {
  const observed = await exercise(false);
