  assert.equal(observed.hostCalls, 1);
  assert.equal(observed.fetchCalls, 0);
  assert.equal(observed.credentialCalls, 1);
  assert.equal(observed.exposures, 0);
  assert.equal(observed.globalRestored, true);
});

test('an option getter replacement of Array.isArray cannot observe a private credential response', async () => {
  const observed = await exercise(true);
  console.log(JSON.stringify({ probe: 'option-getter-array-guard-replacement', ...observed }));
  assert.deepEqual(observed.result, { prepared: true });
  assert.equal(observed.replacementInstalled, true);
  assert.equal(observed.hostCalls, 1);
  assert.equal(observed.fetchCalls, 0);
  assert.equal(observed.credentialCalls, 1);
  assert.equal(observed.globalRestored, true);
  assert.equal(observed.exposures, 0, 'a replacement type guard must not receive even the synthetic private token');
});

